  app.post('/app/api/client/auth/login', async (req, res) => {
    sendNoCache(res);
    const username = toText(req.body?.username);
    const password = String(req.body?.password || '');
    if (!username || !password) {
      return res.status(400).json({ ok: false, error: 'Username/email dan password wajib diisi.' });
    }

    try {
      await ensureClientPortalSchema(pool);
      const user = await authenticateClientPortalUser(pool, username, password)
        || await authenticateInternalClientPortalAdmin(pool, username, password);
      if (!user) {
        await logClientPortalActivity(pool, {
          eventType: 'login',
          status: 'failed',
          detail: username,
          req
        });
        return res.status(401).json({ ok: false, error: 'Username/email atau password salah.' });
      }

      res.cookie(SESSION_COOKIE, createClientPortalSessionCookie(user, sign), sessionCookieOptions(req));
      await pool.query(
        `update client_portal_accounts
         set last_login_at = now(), updated_at = now()
         where id = $1`,
        [user.account.id]
      );
      await logClientPortalActivity(pool, {
        accountId: user.account.id,
        clientId: user.client.id,
        eventType: 'login',
        status: 'success',
        detail: user.account.username,
        req
      });
      return res.json({ ok: true, redirectUrl: '/app/client' });
    } catch (err) {
      return res.status(500).json({ ok: false, error: err.message });
    }
  });

  app.post('/app/api/client/auth/logout', async (req, res) => {
    const sessionUser = await hydrateClientPortalSession(pool, req, sign).catch(() => null);
    if (sessionUser) {
      await logClientPortalActivity(pool, {
        accountId: sessionUser.account.id,
        clientId: sessionUser.client.id,
        eventType: 'logout',
        status: 'success',
        detail: sessionUser.account.username,
        req
      });
    }
    clearClientPortalSession(res);
    sendNoCache(res);
    return res.json({
      ok: true,
      redirectUrl: isAutoAccessRequest(req)
        ? '/app/client'
        : '/app/client/login'
    });
  });

