  app.post('/app/api/client/mobile-uploads/qr', requireClientSession, async (req, res) => {
    sendNoCache(res);
    try {
      const client = await loadClientPortalClientDetail(pool, req.clientPortalUser, req.body?.clientId);
      if (!client) return res.status(404).json({ ok: false, error: 'Klien tidak ditemukan atau tidak tersedia untuk akun ini.' });
      const session = await createClientPortalMobileUploadSession(pool, req, req.clientPortalUser, client, req.body?.label);
      const url = clientPortalMobileUploadUrl(req, session.token);
      const svg = await QRCode.toString(url, {
        type: 'svg',
        margin: 1,
        width: 240,
        color: {
          dark: '#0f766e',
          light: '#ffffff'
        }
      });
      return res.json({
        ok: true,
        token: session.token,
        url,
        svg,
        expiresAt: toIsoDateTime(session.expiresAt)
      });
    } catch (err) {
      return res.status(err.statusCode || 500).json({ ok: false, error: err.message });
    }
  });

  app.get('/app/api/client/mobile-uploads/:token/status', requireClientSession, async (req, res) => {
    sendNoCache(res);
    try {
      const session = await loadClientPortalMobileUploadSession(pool, req.params.token);
      if (!session || session.expired) return res.status(404).json({ ok: false, error: 'Sesi upload QR sudah kedaluwarsa.' });
      const client = await loadClientPortalClientDetail(pool, req.clientPortalUser, session.clientId);
      if (!client || toText(session.accountId) !== toText(req.clientPortalUser.account?.id)) {
        return res.status(403).json({ ok: false, error: 'Sesi upload QR tidak tersedia untuk akun ini.' });
      }
      return res.json({
        ok: true,
        token: session.token,
        label: session.label,
        files: session.files,
        expiresAt: toIsoDateTime(session.expiresAt)
      });
    } catch (err) {
      return res.status(err.statusCode || 500).json({ ok: false, error: err.message });
    }
  });

