  app.get('/app/api/client/clients/:clientId/buku-bank/advances', requireClientSession, async (req, res) => {
    sendNoCache(res);
    try {
      const client = await loadClientPortalClientDetail(pool, req.clientPortalUser, req.params.clientId);
      if (!client || !isHtiPurchaseFpClient(client)) {
        return res.status(404).json({ ok: false, error: 'Uang muka Buku Bank hanya tersedia untuk klien PTX.' });
      }
      const bank = findClientPortalBank(req.query.bank, client);
      return res.json({ ok: true, client, activeBank: bank, advances: await loadClientPortalHtiAdvanceEntries(pool, client.id, bank.key) });
    } catch (err) {
      return res.status(err.statusCode || 500).json({ ok: false, error: err.message });
    }
  });

  app.post('/app/api/client/clients/:clientId/buku-bank/pt-x-party-master', requireClientSession, async (req, res) => {
    sendNoCache(res);
    try {
      const db = await pool.connect();
      let party;
      try {
        await db.query('begin');
        await ensureClientPortalSchema(db);
        const client = await loadClientPortalClientDetail(db, req.clientPortalUser, req.params.clientId);
        if (!client || !isHtiPurchaseFpClient(client)) throw httpError(404, 'Master supplier/customer hanya tersedia untuk klien PTX.');
        party = await upsertClientPortalHtiPartyMaster(
          db,
          client.id,
          toText(req.body?.partyType || req.body?.party_type),
          req.body || {}
        );
        await db.query('commit');
        const result = await loadClientPortalBukuBank(pool, req.clientPortalUser, client.id, req.body?.bankKey || req.body?.bank_key, {});
        return res.json({ ok: true, party, ...result });
      } catch (err) {
        await db.query('rollback').catch(() => {});
        throw err;
      } finally {
        db.release();
      }
    } catch (err) {
      return res.status(err.statusCode || 500).json({ ok: false, error: err.message });
    }
  });

