async function applyClientPortalTbbCleanDeploymentMigration(db) {
  const ownsConnection = typeof db.connect === 'function';
  const connection = ownsConnection ? await db.connect() : db;
  let transactionOpen = false;
  try {
    await connection.query('begin');
    transactionOpen = true;
    await connection.query(`
      create table if not exists client_portal_data_migrations (
        migration_id text not null,
        client_id text not null,
        client_name text not null default '',
        deleted_counts jsonb not null default '{}'::jsonb,
        applied_at timestamptz not null default now(),
        primary key (migration_id, client_id)
      )
    `);
    await connection.query(
      `select pg_advisory_xact_lock(hashtext($1), hashtext($2))`,
      [DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_MIGRATION_ID, DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_ID]
    );

    const applied = await connection.query(
      `select 1
       from client_portal_data_migrations
       where migration_id = $1 and client_id = $2
       limit 1`,
      [DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_MIGRATION_ID, DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_ID]
    );
    if (applied.rows.length) {
      await connection.query('commit');
      transactionOpen = false;
      return;
    }

    const clientResult = await connection.query(
      `select id::text, nama_klien
       from clients
       where id::text = $1
       limit 1`,
      [DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_ID]
    );
    const client = clientResult.rows[0];
    if (!client || toText(client.nama_klien).toUpperCase() !== DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_NAME) {
      await connection.query('commit');
      transactionOpen = false;
      return;
    }

    const deletedCounts = {};
    for (const tableName of DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_TRANSACTION_TABLES) {
      const result = await connection.query(
        `delete from ${tableName} where client_id = $1`,
        [DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_ID]
      );
      deletedCounts[tableName] = Number(result.rowCount || 0);
    }

    await connection.query(
      `insert into client_portal_data_migrations
         (migration_id, client_id, client_name, deleted_counts)
       values ($1,$2,$3,$4::jsonb)`,
      [
        DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_MIGRATION_ID,
        DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_ID,
        DEMO_DISTRIBUTION_CLEAN_DEPLOYMENT_CLIENT_NAME,
        JSON.stringify(deletedCounts)
      ]
    );
    await connection.query('commit');
    transactionOpen = false;
  } catch (err) {
    if (transactionOpen) await connection.query('rollback').catch(() => {});
    throw err;
  } finally {
    if (ownsConnection) connection.release();
  }
}

async function createClientPortalMobileUploadSession(db, req, sessionUser, client, labelInput) {
  await ensureClientPortalSchema(db);
  const token = crypto.randomBytes(24).toString('base64url');
  const expiresAt = new Date(Date.now() + CLIENT_PORTAL_MOBILE_UPLOAD_TTL_MS);
  const label = toText(labelInput) || 'Upload File';
  await db.query(
    `insert into client_portal_mobile_upload_sessions
       (token, client_id, account_id, label, files_json, expires_at)
     values ($1, $2, $3, $4, '[]'::jsonb, $5)`,
    [token, toText(client.id), toText(sessionUser.account?.id), label.slice(0, 120), expiresAt]
  );
  await logClientPortalActivity(db, {
    accountId: sessionUser.account?.id,
    clientId: client.id,
    eventType: 'mobile_upload_qr',
    status: 'success',
    detail: label,
    req
  });
  return { token, clientId: client.id, accountId: sessionUser.account?.id, label, expiresAt };
}

async function loadClientPortalMobileUploadSession(db, tokenInput) {
  await ensureClientPortalSchema(db);
  const token = toText(tokenInput);
  if (!token) return null;
  const result = await db.query(
    `select token, client_id, account_id, label, files_json, expires_at
     from client_portal_mobile_upload_sessions
     where token = $1
     limit 1`,
    [token]
  );
  if (!result.rows.length) return null;
  const row = result.rows[0];
  const expiresAt = row.expires_at instanceof Date ? row.expires_at : new Date(row.expires_at);
  return {
    token: toText(row.token),
    clientId: toText(row.client_id),
    accountId: toText(row.account_id),
    label: toText(row.label) || 'Upload File',
    files: normalizeClientPortalStoredMobileFiles(row.files_json),
    expiresAt,
    expired: expiresAt.getTime() <= Date.now()
  };
}

async function saveClientPortalMobileUploadFiles(db, tokenInput, filesInput) {
  const session = await loadClientPortalMobileUploadSession(db, tokenInput);
  if (!session || session.expired) throw httpError(404, 'Sesi upload QR sudah kedaluwarsa.');
  const files = normalizeClientPortalMobileUploadFiles(filesInput);
  await db.query(
    `update client_portal_mobile_upload_sessions
     set files_json = $2::jsonb, updated_at = now()
     where token = $1`,
    [session.token, JSON.stringify(files)]
  );
  return {
    token: session.token,
    count: files.length,
    files: files.map(file => ({
      id: file.id,
      name: file.name,
      mimeType: file.mimeType,
      size: file.size,
      uploadedAt: file.uploadedAt
    }))
  };
}

function normalizeClientPortalStoredMobileFiles(value) {
  const files = Array.isArray(value) ? value : [];
  return files.map(file => ({
    id: toText(file?.id) || crypto.randomUUID(),
    name: (toText(file?.name) || 'lampiran').slice(0, 180),
    mimeType: (toText(file?.mimeType || file?.type) || 'application/octet-stream').slice(0, 120),
    size: parseClientPortalAttachmentSize(file?.size),
    dataUrl: toText(file?.dataUrl),
    uploadedAt: toText(file?.uploadedAt)
  })).filter(file => file.dataUrl);
}

function normalizeClientPortalMobileUploadFiles(filesInput) {
  const files = Array.isArray(filesInput) ? filesInput : [];
  if (!files.length) throw httpError(400, 'Pilih minimal satu file.');
  if (files.length > 30) throw httpError(400, 'Maksimal 30 file per upload QR.');
  let totalSize = 0;
  const normalized = files.map(file => {
    const dataUrl = normalizeClientPortalAttachmentDataUrl(file?.dataUrl);
    const size = parseClientPortalAttachmentSize(file?.size);
    totalSize += size;
    return {
      id: toText(file?.id) || crypto.randomUUID(),
      name: (toText(file?.name) || 'lampiran').slice(0, 180),
      mimeType: (toText(file?.mimeType || file?.type) || 'application/octet-stream').slice(0, 120),
      size,
      dataUrl,
      uploadedAt: toText(file?.uploadedAt) || new Date().toISOString()
    };
  });
  if (totalSize > 120 * 1024 * 1024) throw httpError(413, 'Total file upload maksimal 120 MB.');
  return normalized;
}

function clientPortalPublicBaseUrl(req) {
  const forwardedProto = toText(req.get('x-forwarded-proto')).split(',')[0].trim();
  const forwardedHost = toText(req.get('x-forwarded-host')).split(',')[0].trim();
  const proto = forwardedProto || (req.secure ? 'https' : 'http');
  const host = forwardedHost || toText(req.get('host'));
  return `${proto}://${host}`;
}

function clientPortalMobileUploadUrl(req, token) {
  return `${clientPortalPublicBaseUrl(req)}/app/client/mobile-upload/${encodeURIComponent(token)}`;
}

function clientPortalMobileUploadPage(session) {
  const invalid = !session || session.invalid;
  const title = invalid ? 'QR upload tidak tersedia' : 'Upload File Portal Klien';
  const label = invalid ? 'Sesi upload sudah kedaluwarsa atau tidak ditemukan.' : session.label;
  const token = invalid ? '' : session.token;
  const error = session?.error ? `<p class="error">${escapeClientPortalHtml(session.error)}</p>` : '';
  return `<!doctype html>
<html lang="id">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeClientPortalHtml(title)}</title>
  <style>
    *{box-sizing:border-box}
    body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f8fafc;color:#172033;font-family:Arial,sans-serif;padding:18px}
    main{width:min(100%,440px);border:1px solid #dbe5ef;border-radius:12px;background:#fff;box-shadow:0 18px 50px rgba(15,23,42,.14);padding:22px}
    h1{margin:0 0 8px;font-size:22px;line-height:1.25}
    p{margin:0 0 16px;color:#64748b;line-height:1.45}
    label{display:grid;gap:8px;margin-bottom:16px;font-weight:800;color:#172033}
    input{width:100%;min-height:44px;border:1px solid #ccd8e5;border-radius:8px;padding:10px;background:#fff;color:#172033}
    button{width:100%;min-height:46px;border:0;border-radius:8px;background:#ba1a1a;color:#fff;font-size:16px;font-weight:900;cursor:pointer}
    button:disabled{background:#94a3b8;cursor:not-allowed}
    .status{margin-top:14px;color:#0f766e;font-weight:800}
    .error{color:#b91c1c;font-weight:800}
  </style>
</head>
<body>
  <main>
    <h1>${escapeClientPortalHtml(title)}</h1>
    <p>${escapeClientPortalHtml(label)}</p>
    ${error}
    ${invalid ? '' : '<label>Pilih file dari HP<input id="files" type="file" multiple></label><button id="submit" type="button">Upload File</button><p class="status" id="status"></p>'}
  </main>
  <script>
    const token = ${JSON.stringify(token)};
    const input = document.getElementById('files');
    const button = document.getElementById('submit');
    const statusEl = document.getElementById('status');
    function fileToDataUrl(file) {
      return new Promise(function(resolve, reject) {
        const reader = new FileReader();
        reader.onload = function() { resolve(String(reader.result || '')); };
        reader.onerror = function() { reject(new Error('Gagal membaca file.')); };
        reader.readAsDataURL(file);
      });
    }
    if (button) {
      button.addEventListener('click', async function() {
        const files = Array.from(input.files || []);
        if (!files.length) {
          statusEl.textContent = 'Pilih minimal satu file.';
          return;
        }
        button.disabled = true;
        statusEl.textContent = 'Mengupload file...';
        try {
          const payload = [];
          for (const file of files) {
            payload.push({
              id: (window.crypto && window.crypto.randomUUID ? window.crypto.randomUUID() : String(Date.now()) + Math.random()),
              name: file.name,
              mimeType: file.type || 'application/octet-stream',
              size: file.size || 0,
              dataUrl: await fileToDataUrl(file),
              uploadedAt: new Date().toISOString()
            });
          }
          const response = await fetch('/app/api/client/mobile-uploads/' + encodeURIComponent(token) + '/files', {
            method: 'POST',
            headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' },
            body: JSON.stringify({ files: payload })
          });
          const data = await response.json().catch(function() { return {}; });
          if (!response.ok || data.ok === false) throw new Error(data.error || 'Upload gagal.');
          statusEl.textContent = data.count + ' file berhasil dikirim. Silakan kembali ke komputer.';
        } catch (err) {
          statusEl.textContent = err.message || 'Upload gagal.';
          button.disabled = false;
        }
      });
    }
  </script>
</body>
</html>`;
}

