  const actor = toText(sessionUser?.account?.username) || 'client_portal';
  const result = await pool.query(
    `update client_portal_hti_purchase_fp_entries
     set documents_uploaded = $1, updated_by = $2, updated_at = now()
     where id::text = $3 and client_id = $4
     returning id::text`,
    [documentsUploaded, actor, toText(entryId), client.id]
  );
  if (!result.rows.length) throw httpError(404, 'Data Buku Pembelian FP tidak ditemukan.');
