async function loadClientPortalPoCustomerEntries(db, clientId) {
  const result = await db.query(
    `select id::text,
            item_no,
            po_no,
            po_date,
            customer_name,
            product_name,
            brand_type,
            specification,
            illustration,
            unit,
            unit_price,
            requested_qty,
            requested_total,
            requested_dpp,
            requested_ppn,
            notes,
            supplier_name,
            purchase_invoice_no,
            purchase_date,
            purchase_unit_price,
            purchase_qty,
            purchase_total,
            purchase_tax_mode,
            purchase_dpp,
            purchase_ppn,
            purchase_lines,
            realization_notes,
            attachment_name,
            attachment_mime_type,
            attachment_size,
            attachment_data_url <> '' as has_attachment,
            created_at,
            updated_at
     from client_portal_po_customer_entries
     where client_id = $1
     order by po_date desc, created_at desc, id desc`,
    [toText(clientId)]
  );
  return result.rows.map(mapClientPortalPoCustomerRow);
}

