async function loadClientPortalBukuBesarSalesRows(db, clientId) {
  const [result, manualPaymentResult, hppResult, bbnResult] = await Promise.all([
    db.query(
    `select source_id,
            source_stage,
            business_entity_key,
            business_entity_name,
            entry_date,
            no_bukti,
            customer_name,
            frame_no,
            amount,
            ppn_amount,
            payment_source_type,
            payment_source_key,
            payment_source_coa,
            payment_source_account_name,
            payment_rows,
            payment_notes,
            created_at
     from (
       select id::text as source_id,
              'dp' as source_stage,
              business_entity_key,
              business_entity_name,
              entry_date,
              receipt_no as no_bukti,
              customer_name,
              frame_no,
              dpp as amount,
              ppn as ppn_amount,
              'kas' as payment_source_type,
              'kas-besar' as payment_source_key,
              '1-1003' as payment_source_coa,
              'KAS 2' as payment_source_account_name,
              '[]'::jsonb as payment_rows,
              '' as payment_notes,
              created_at
       from client_portal_buku_penjualan_dp_entries
       where client_id = $1
       union all
       select pelunasan.id::text as source_id,
              'pelunasan' as source_stage,
              pelunasan.business_entity_key,
              pelunasan.business_entity_name,
              pelunasan.invoice_date as entry_date,
              pelunasan.invoice_no as no_bukti,
              coalesce(dp.customer_name, lengkap.customer_name, '') as customer_name,
              coalesce(dp.frame_no, lengkap.frame_no, '') as frame_no,
              pelunasan.dpp_settlement as amount,
              pelunasan.ppn_settlement as ppn_amount,
              pelunasan.pelunasan_source_type as payment_source_type,
              pelunasan.pelunasan_source_key as payment_source_key,
              pelunasan.pelunasan_source_coa as payment_source_coa,
              pelunasan.pelunasan_source_account_name as payment_source_account_name,
              pelunasan.pelunasan_payment_rows as payment_rows,
              pelunasan.pelunasan_notes as payment_notes,
              pelunasan.created_at
       from client_portal_buku_penjualan_pelunasan_entries pelunasan
       left join client_portal_buku_penjualan_dp_entries dp
         on dp.id = pelunasan.dp_entry_id
        and dp.client_id = pelunasan.client_id
       left join client_portal_buku_penjualan_lengkap_entries lengkap
         on lengkap.id = pelunasan.complete_entry_id
        and lengkap.client_id = pelunasan.client_id
       where pelunasan.client_id = $1
       union all
       select id::text as source_id,
              'lengkap' as source_stage,
              business_entity_key,
              business_entity_name,
              coalesce(invoice_date, entry_date) as entry_date,
              coalesce(nullif(invoice_no, ''), receipt_no) as no_bukti,
              customer_name,
              frame_no,
              dpp as amount,
              ppn as ppn_amount,
              'kas' as payment_source_type,
              'kas-besar' as payment_source_key,
              '1-1003' as payment_source_coa,
              'KAS 2' as payment_source_account_name,
              '[]'::jsonb as payment_rows,
              '' as payment_notes,
              created_at
       from client_portal_buku_penjualan_lengkap_entries
       where client_id = $1
     ) sales
     where amount <> 0 or ppn_amount <> 0
     order by entry_date, created_at, source_stage, source_id`,
      [toText(clientId)]
    ),
    db.query(
      `select greatest(
                0,
                coalesce(sum(case
                  when money_in > 0 then money_in
                  when money_out > 0 then -money_out
                  else 0
                end), 0)
              ) as amount
       from (
         select money_in, money_out
         from client_portal_buku_kas_entries
         where client_id = $1 and coa_code = $2
         union all
         select money_in, money_out
         from client_portal_buku_bank_entries
         where client_id = $1 and coa_code = $2
       ) manual_payments`,
      [toText(clientId), CLIENT_PORTAL_SALES_RECEIVABLE_ACCOUNT.coa]
    ),
    db.query(
      `select stock.id::text as stock_id,
              stock.business_entity_key,
              stock.business_entity_name,
              stock.stock_date,
              stock.source_no as stock_source_no,
              stock.item_name,
              stock.color,
              stock.frame_no,
              stock.engine_no,
              stock.dpp as cost_amount,
              sale.source_id,
              sale.source_stage,
              sale.entry_date,
              sale.no_bukti,
              sale.customer_name,
              sale.created_at
       from client_portal_buku_persediaan_entries stock
       join lateral (
         select candidate.source_id,
                candidate.source_stage,
                candidate.entry_date,
                candidate.no_bukti,
                candidate.customer_name,
                candidate.created_at
         from (
           select dp.id::text as source_id,
                  'dp' as source_stage,
                  dp.entry_date,
                  dp.receipt_no as no_bukti,
                  dp.customer_name,
                  dp.created_at
           from client_portal_buku_penjualan_dp_entries dp
           where dp.client_id = stock.client_id
             and stock.frame_no <> ''
             and upper(dp.frame_no) = upper(stock.frame_no)
           union all
           select lengkap.id::text as source_id,
                  'lengkap' as source_stage,
                  coalesce(lengkap.invoice_date, lengkap.entry_date) as entry_date,
                  coalesce(nullif(lengkap.invoice_no, ''), lengkap.receipt_no) as no_bukti,
                  lengkap.customer_name,
                  lengkap.created_at
           from client_portal_buku_penjualan_lengkap_entries lengkap
           where lengkap.client_id = stock.client_id
             and stock.frame_no <> ''
             and upper(lengkap.frame_no) = upper(stock.frame_no)
         ) candidate
         order by candidate.entry_date, candidate.created_at, candidate.source_stage, candidate.source_id
         limit 1
       ) sale on true
       where stock.client_id = $1
         and stock.frame_no <> ''
         and coalesce(stock.dpp, 0) <> 0
       order by sale.entry_date, sale.created_at, stock.id`,
      [toText(clientId)]
    ),
    db.query(
      `select source_id,
              source_stage,
              business_entity_key,
              business_entity_name,
              entry_date,
              no_bukti,
              customer_name,
              frame_no,
              bbn_notice,
              is_paid,
              payment_source_type,
              payment_source_key,
              payment_source_coa,
              payment_source_account_name,
              payment_rows,
              payment_notes,
              created_at
       from (
         select dp.id::text as source_id,
                'dp' as source_stage,
                coalesce(pelunasan.business_entity_key, dp.business_entity_key) as business_entity_key,
                coalesce(pelunasan.business_entity_name, dp.business_entity_name) as business_entity_name,
                coalesce(pelunasan.invoice_date, dp.entry_date) as entry_date,
                coalesce(nullif(pelunasan.invoice_no, ''), dp.receipt_no) as no_bukti,
                dp.customer_name,
                dp.frame_no,
                case
                  when pelunasan.id is not null then coalesce(nullif(pelunasan.bbn_notice, 0), dp.bbn_notice)
                  else dp.bbn_notice
                end as bbn_notice,
                pelunasan.id is not null as is_paid,
                pelunasan.pelunasan_source_type as payment_source_type,
                pelunasan.pelunasan_source_key as payment_source_key,
                pelunasan.pelunasan_source_coa as payment_source_coa,
                pelunasan.pelunasan_source_account_name as payment_source_account_name,
                pelunasan.pelunasan_payment_rows as payment_rows,
                pelunasan.pelunasan_notes as payment_notes,
                coalesce(pelunasan.created_at, dp.created_at) as created_at
         from client_portal_buku_penjualan_dp_entries dp
         left join lateral (
           select id,
                  business_entity_key,
                  business_entity_name,
                  invoice_date,
                  invoice_no,
                  bbn_notice,
                  pelunasan_source_type,
                  pelunasan_source_key,
                  pelunasan_source_coa,
                  pelunasan_source_account_name,
                  pelunasan_payment_rows,
                  pelunasan_notes,
                  created_at
           from client_portal_buku_penjualan_pelunasan_entries pelunasan
           where pelunasan.client_id = dp.client_id
             and pelunasan.dp_entry_id = dp.id
           order by pelunasan.invoice_date desc, pelunasan.created_at desc, pelunasan.id desc
           limit 1
         ) pelunasan on true
         where dp.client_id = $1
         union all
          select lengkap.id::text as source_id,
                 'lengkap' as source_stage,
                 coalesce(pelunasan.business_entity_key, lengkap.business_entity_key) as business_entity_key,
                 coalesce(pelunasan.business_entity_name, lengkap.business_entity_name) as business_entity_name,
                 coalesce(pelunasan.invoice_date, lengkap.invoice_date, lengkap.entry_date) as entry_date,
                 coalesce(nullif(pelunasan.invoice_no, ''), nullif(lengkap.invoice_no, ''), lengkap.receipt_no) as no_bukti,
                 lengkap.customer_name,
                 lengkap.frame_no,
                 case
                   when pelunasan.id is not null then coalesce(nullif(pelunasan.bbn_notice, 0), lengkap.bbn_notice)
                   else lengkap.bbn_notice
                 end as bbn_notice,
                 pelunasan.id is not null as is_paid,
                 pelunasan.pelunasan_source_type as payment_source_type,
                 pelunasan.pelunasan_source_key as payment_source_key,
                 pelunasan.pelunasan_source_coa as payment_source_coa,
                 pelunasan.pelunasan_source_account_name as payment_source_account_name,
                 pelunasan.pelunasan_payment_rows as payment_rows,
                 pelunasan.pelunasan_notes as payment_notes,
                 coalesce(pelunasan.created_at, lengkap.created_at) as created_at
          from client_portal_buku_penjualan_lengkap_entries lengkap
          left join lateral (
            select id,
                   business_entity_key,
                   business_entity_name,
                   invoice_date,
                   invoice_no,
                   bbn_notice,
                   pelunasan_source_type,
                   pelunasan_source_key,
                   pelunasan_source_coa,
                   pelunasan_source_account_name,
                   pelunasan_payment_rows,
                   pelunasan_notes,
                   created_at
            from client_portal_buku_penjualan_pelunasan_entries pelunasan
            where pelunasan.client_id = lengkap.client_id
              and pelunasan.complete_entry_id = lengkap.id
            order by pelunasan.invoice_date desc, pelunasan.created_at desc, pelunasan.id desc
            limit 1
          ) pelunasan on true
          where lengkap.client_id = $1
       ) bbn
       where coalesce(bbn_notice, 0) <> 0
       order by entry_date, created_at, source_stage, source_id`,
      [toText(clientId)]
    )
  ]);
  let manualPaymentCoverage = Number(manualPaymentResult.rows[0]?.amount || 0);
  const salesJournalRows = result.rows.flatMap(row => {
    const receivableAmount = Number(row.amount || 0) + Number(row.ppn_amount || 0);
    if (row.source_stage === 'lengkap') {
      return mapClientPortalSalesJournalRows(row, { autoPaymentAmount: 0 });
    }
    const coveredByManualPayment = Math.min(Math.max(manualPaymentCoverage, 0), Math.max(receivableAmount, 0));
    manualPaymentCoverage = Math.max(0, manualPaymentCoverage - coveredByManualPayment);
    return mapClientPortalSalesJournalRows(row, {
      autoPaymentAmount: Math.max(0, receivableAmount - coveredByManualPayment)
    });
  });
  const hppJournalRows = hppResult.rows.flatMap(row => mapClientPortalSalesHppJournalRows(row));
  const bbnJournalRows = bbnResult.rows.flatMap(row => mapClientPortalSalesBbnNoticeJournalRows(row));
  return [...salesJournalRows, ...hppJournalRows, ...bbnJournalRows];
}

